from produire import produire,paras,steps,table
from medicaments import mometasone_polypes
produire(7,[
('La {rhinosinusite chronique avec polypes} associe une inflammation chronique et des polypes nasaux bilatéraux objectivés. L’obstruction et la perte d’odorat peuvent être importantes. Une masse unilatérale n’est pas assimilée d’emblée à cette forme habituelle.',paras('EPOS définit une rhinosinusite d’au moins douze semaines avec symptômes compatibles et polypes visualisés dans les méats moyens à l’endoscopie. Le terme polype décrit un aspect ; une lésion atypique doit être caractérisée plutôt que présumée bénigne.')),
('Le {contexte respiratoire est essentiel}. Asthme et réactions respiratoires aux anti-inflammatoires peuvent être associés. Une atteinte chez l’enfant ou une présentation atypique appelle une recherche de cause particulière.',paras('Demander réactions après aspirine ou autres anti-inflammatoires non stéroïdiens, sans proposer un test de prise à domicile. Chez l’enfant, envisager notamment une maladie sous-jacente selon le contexte ; les indications et doses d’adulte ne sont pas transposées. Aucune fréquence suisse précise n’est inventée.')),
('L’{inflammation peut comporter une composante de type deux}. Œdème et remodelage muqueux contribuent aux polypes. La biologie est hétérogène et peut influencer la réponse aux traitements.',paras('Le phénotype visible ne résume pas tous les mécanismes. Éosinophiles et autres marqueurs peuvent aider dans un bilan spécialisé, notamment avant traitement ciblé ; un test isolé n’établit pas toute la maladie et n’autorise pas seul une biothérapie.')),
('Les {drapeaux rouges doivent être distingués d’une polypose diffuse}. Masse unilatérale irrégulière, ulcération ou saignement impose un examen approfondi. Trouble visuel, déficit ou signe orbitaire appelle une prise en charge urgente.',paras('La notice suisse de mométasone demande expressément d’explorer les polypes unilatéraux inhabituels ou saignants. Une maladie connue n’explique pas automatiquement un signe nouveau ; ne pas retarder l’exploration par des cures répétées de corticoïdes.')),
('L’{anamnèse explore odorat, obstruction et contrôle antérieur}. Mesurer retentissement, sommeil et qualité de vie. Relever cures systémiques, chirurgies, traitements locaux et leur observance.',paras('Évaluer l’asthme et les réactions médicamenteuses respiratoires. Une perte d’odorat peut exposer aux aliments altérés ou à la non-détection de fumée ; demander son impact pratique et prévoir des mesures de sécurité. Une plainte isolée d’odorat garde d’autres diagnostics possibles.')),
('L’{examen endoscopique confirme la distribution}. Il recherche les polypes des deux côtés et les autres signes d’inflammation. L’examen décrit aussi tout aspect inhabituel.',paras('Une évaluation de l’odorat peut objectiver la gêne. L’examen respiratoire et le bilan d’asthme sont adaptés aux symptômes ; l’évaluation ne s’arrête pas au nez si les voies respiratoires inférieures sont concernées.')),
('L’{approche syndromique} distingue maladie diffuse et masse focale. Le retentissement ne dépend pas uniquement du volume visible. Asthme, odorat et recours aux corticoïdes systémiques participent à l’évaluation.',table(['Constat','Question clinique'],[['Polypes bilatéraux avec symptômes chroniques.','Forme diffuse et niveau de contrôle ?'],['Masse unilatérale ou saignante.','Autre lésion à caractériser ?'],['Asthme et réaction aux anti-inflammatoires.','Maladie respiratoire exacerbée par ces médicaments ?'],['Récidive malgré soins et chirurgie adaptés.','Observance, mécanisme inflammatoire et traitement spécialisé à réévaluer ?']])) ,
('Le {diagnostic positif associe critères chroniques et endoscopie}. Les polypes bilatéraux au méat moyen caractérisent le phénotype habituel. Une image seule ou le mot polype dans un ancien courrier ne remplace pas l’évaluation actuelle.',paras('Le cadre clinique comprend au moins deux symptômes, dont obstruction ou écoulement, avec éventuellement douleur/pression et perte d’odorat. L’imagerie peut préciser l’extension ; les investigations histologiques sont discutées devant atypie ou intervention selon le contexte.')),
('Les {examens préparent une stratégie individualisée}. Le scanner aide à apprécier l’extension et à planifier la chirurgie lorsqu’elle est envisagée. Les examens biologiques et respiratoires répondent à une question précise.',paras('Une IRM peut être nécessaire pour une masse ou une extension particulière. Les marqueurs inflammatoires, l’évaluation allergologique ou celle de l’asthme ne sont pas des substituts à l’endoscopie ; ils complètent le profil clinique et les décisions spécialisées.')),
('L’{algorithme} associe traitement local, contrôle et escalade ciblée. La technique et l’adhésion sont vérifiées avant de conclure à l’échec. Les signes atypiques suivent une filière d’exploration propre.',steps('Confirmer la forme bilatérale chronique et exclure une masse atypique.', 'Évaluer odorat, qualité de vie, asthme et réactions médicamenteuses.', 'Instaurer soins salins et traitement nasal approprié avec suivi.', 'Si contrôle insuffisant, discuter options spécialisées, dont chirurgie ou traitement ciblé selon indication actuelle ; poursuivre les soins après intervention.')),
('La {prise en charge initiale comprend habituellement un corticoïde nasal}. Le traitement régulier et les soins salins restent importants. Les formes sévères nécessitent une décision spécialisée sur les autres options.',paras('Un bref traitement corticoïde systémique peut être discuté dans certaines situations, avec évaluation des risques cumulatifs ; il ne doit pas devenir une répétition automatique. Chirurgie et traitements biologiques relèvent d’une sélection spécialisée selon la maladie, les traitements déjà suivis et les indications suisses actualisées.', '@@MEDICAMENTS@@', 'Les critères européens historiques de biothérapie ne sont pas présentés comme des conditions actuelles de remboursement suisse. Aucun seuil ou dosage de biothérapie non vérifié n’est proposé. Une chirurgie améliore l’accès aux soins et le contrôle de certains symptômes, mais la maladie peut récidiver et nécessite un traitement de fond.')),
('La {prévention repose sur un suivi prolongé}. Maintenir les soins prescrits et traiter l’asthme associé. Documenter les réactions aux anti-inflammatoires pour sécuriser les prescriptions.',paras('Une désensibilisation médicamenteuse éventuelle relève d’un cadre spécialisé, jamais d’un essai personnel. En cas d’anosmie, utiliser des détecteurs adaptés et vérifier conservation et dates des aliments ; la sécurité ne repose pas sur le seul odorat.')),
('Le {point clé} est une maladie inflammatoire souvent durable. La bilatéralité et l’endoscopie orientent la classification. La persistance appelle un plan de contrôle, pas seulement une réduction ponctuelle du volume des polypes.',paras('La dose et l’âge autorisés dépendent de l’indication de la spécialité. Une masse unilatérale saignante sort du cadre de la polypose diffuse habituelle et doit être explorée.'))
],[
('Quelle distribution caractérise la polypose chronique habituelle selon EPOS ?','Des polypes bilatéraux visualisés au méat moyen.'),
('Quel délai est requis pour les symptômes chroniques ?','Au moins douze semaines.'),
('Un polype unilatéral saignant doit-il être simplement traité par spray ?','Non, il nécessite une exploration.'),
('Quels symptômes retentissent souvent fortement ?','L’obstruction et la perte d’odorat.'),
('Quelle comorbidité respiratoire faut-il rechercher ?','L’asthme.'),
('Peut-on tester chez soi une réaction à l’aspirine ?','Non.'),
('Un marqueur de type deux suffit-il seul à prescrire une biothérapie ?','Non.'),
('Quel âge minimal concerne l’indication polypes de Nasonex citée ?','Dix-huit ans.'),
('Quelle dose initiale quotidienne totale cite cette notice pour les polypes ?','Quatre cents microgrammes, en deux pulvérisations par narine deux fois par jour.'),
('La réduction après contrôle est-elle la même dose totale ?','Non, deux cents microgrammes par jour selon la notice.'),
('Une absence d’amélioration après cinq à six semaines appelle-t-elle une poursuite aveugle ?','Non, la notice demande d’envisager un changement de thérapie.'),
('Les critères européens de biothérapie prouvent-ils le remboursement suisse ?','Non.'),
('La chirurgie élimine-t-elle toujours le besoin de soins locaux ?','Non.'),
('Pourquoi discuter la sécurité domestique en cas d’anosmie ?','L’odorat ne permet plus de détecter de façon fiable certains dangers ou aliments altérés.')
],(2,4,10,12),mometasone_polypes)
